import{_ as o,o as t,c as a,ak as r}from"./chunks/framework.BLy9NAdO.js";const _=JSON.parse('{"title":"概述","description":"","frontmatter":{"title":"概述","sidebar":"概述"},"headers":[],"relativePath":"posts/guide/index.md","filePath":"posts/guide/index.md","lastUpdated":1778742737000}'),i={name:"posts/guide/index.md"};function n(s,e,d,l,c,h){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to “概述”">​</a></h1><p>HeyBoxBot 是一个使用 TypeScript 编写的黑盒聊天机器人框架，用于在<strong>黑盒语音</strong>平台上构建聊天机器人。</p><h2 id="什么是-heyboxbot" tabindex="-1">什么是 HeyBoxBot？ <a class="header-anchor" href="#什么是-heyboxbot" aria-label="Permalink to “什么是 HeyBoxBot？”">​</a></h2><p>HeyBoxBot 封装了黑盒语音的 WebSocket 通信协议和 HTTP API，提供了一套类型安全、事件驱动的开发接口。你可以通过简单的装饰器来注册指令和定时任务，无需关心底层的消息协议。</p><h2 id="核心特性" tabindex="-1">核心特性 <a class="header-anchor" href="#核心特性" aria-label="Permalink to “核心特性”">​</a></h2><ul><li><strong>指令系统</strong> — 通过 <code>@bot.command()</code> 装饰器注册指令，支持字符串、数字、布尔、用户、图片、文件等多种参数类型</li><li><strong>定时任务</strong> — 通过 <code>@bot.cron()</code> 装饰器注册 cron 定时任务</li><li><strong>事件订阅</strong> — 通过 <code>@bot.subscribe()</code> 装饰器订阅房间事件（用户进出、表情反应、卡片按钮点击等）</li><li><strong>扩展 Markdown</strong> — 支持标题、链接、图片、@用户、有序/无序列表、引用等富文本格式</li><li><strong>卡片消息</strong> — 支持构建包含头部、段落、图文、按钮、分割线、倒计时的卡片消息</li><li><strong>完整 API 覆盖</strong> — 房间管理、频道管理、身份组管理、表情管理、直播推流、音频控制等</li></ul><h2 id="许可协议" tabindex="-1">许可协议 <a class="header-anchor" href="#许可协议" aria-label="Permalink to “许可协议”">​</a></h2><p>HeyBoxBot 使用 LGPL-3.0 许可证开源。</p>',8)])])}const b=o(i,[["render",n]]);export{_ as __pageData,b as default};
